import {clone,uid} from './model.js';
import {captureProduct,assertProductSource} from './product-workflow.js';
import {colorParams,COLOR_FIELDS} from './color-settings.js';
export function validateColorRecipe(r,assertSource){if(!r||r.version!==1||r.engine!=='color-scene-v1'||!['garment','beverage'].includes(r.mode))throw Error('Invalid color recipe.');for(const key of ['source','maskSource'])assertSource(r[key]);for(const key of ['cleanSource','inkSource','backgroundSource'])if(r[key])assertSource(r[key]);if(!Number.isInteger(r.width)||!Number.isInteger(r.height)||r.width<1||r.height<1||!Number.isSafeInteger(r.width*r.height*4))throw Error('Invalid color dimensions.');if(!r.params||Object.keys(r.params).length!==Object.keys(COLOR_FIELDS).length+6)throw Error('Incomplete color parameters.');colorParams(r.params);if(r.mode==='garment'&&(r.params.background!=='original'||['blur','sun','bokeh','shadow'].some(k=>r.params[k]!==0)))throw Error('Garment recolor does not replace the person background.');for(const list of [r.strokes,r.inkStrokes])if(!Array.isArray(list)||list.length>80||list.reduce((n,s)=>n+(s.points?.length||0),0)>20000||list.some(s=>s.type!=='color'||typeof s.add!=='boolean'||!Number.isFinite(s.radius)||s.radius<.001||s.radius>.3||!Array.isArray(s.points)||!s.points.length||s.points.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v)||v<0||v>1))))throw Error('Invalid color strokes.');if(r.rect){const q=r.rect;if(!['x','y','width','height'].every(k=>Number.isFinite(q[k]))||q.x<0||q.y<0||q.width<=0||q.height<=0||q.x+q.width>1.001||q.y+q.height>1.001)throw Error('Invalid print rectangle.');}return r;}
export function captureColor(doc,layer){if(doc.selection)throw Error('Bỏ vùng chọn tài liệu trước; dùng cọ trong công cụ để chọn vùng đổi màu.');if(layer?.colorRecipe&&layer.locked)throw Error('Mở khóa layer trước khi sửa màu.');return captureProduct(doc,layer);}
export function applyColor(doc,snapshot,output,recipe,assets){const current=assertProductSource(doc,snapshot),reopen=current.colorRecipe?.mode===recipe.mode;if(current.smartObjectId||current.clipToBelow||reopen&&current.locked)throw Error('Layer không cho phép chỉnh màu.');if(!reopen&&doc.layers.length>=150)throw Error('Đã đạt giới hạn 150 layer.');validateColorRecipe(recipe,s=>{if(typeof s!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(s)&&s!=='assets/wave.jpg')throw Error('Invalid color source.');});if(output?.width!==recipe.width||output?.height!==recipe.height)throw Error('Color output does not match source.');const source=output.toDataURL(),result={...clone(current),source,colorRecipe:clone(recipe)};for(const k of ['photoRecipe','removalRecipe','productRecipe','paperRecipe','cutoutRecipe','landscapeRecipe','sceneRecipe','artRecipe','generation','assistance'])delete result[k];if(!reopen){result.id=uid();result.visible=true;result.locked=false;result.name=current.name.slice(0,130)+(recipe.mode==='garment'?' · Đổi màu trang phục':' · Đồ uống');}if(recipe.params.scene&&recipe.params.background!=='original')delete result.mask;assets.set(source,output);if(reopen){Object.assign(current,result);if(recipe.params.scene&&recipe.params.background!=='original')delete current.mask;}else{doc.layers.splice(doc.layers.indexOf(current)+1,0,result);current.visible=false;}doc.activeId=result.id;doc.selectedIds=[result.id];return result;}
